//! AI Engine Integration for the Knowledge Library
//!\n//! This module provides seamless integration between the knowledge library and AI engines,\n//! enabling enhanced prompt building with contextual knowledge, smart prompt optimization,\n//! and intelligent pattern suggestion systems.\n\nuse crate::ai::knowledge::{\n    schema::*,\n    concurrent::ConcurrentKnowledgeAccess,\n};\nuse crate::analysis::ArchitecturalIssue;\nuse std::sync::Arc;\nuse std::collections::{HashMap, HashSet};\nuse std::time::{Instant, Duration};\nuse lru::LruCache;\nuse parking_lot::Mutex;\nuse serde::{Serialize, Deserialize};\nuse tokio::sync::RwLock;\n\n/// AI integration specific errors\n#[derive(Debug, thiserror::Error)]\npub enum IntegrationError {\n    #[error(\"Pattern context not found: {pattern_id}\")]\n    PatternContextNotFound { pattern_id: String },\n    \n    #[error(\"Token budget exceeded: {current} > {limit}\")]\n    TokenBudgetExceeded { current: usize, limit: usize },\n    \n    #[error(\"Template rendering failed: {template_id} - {reason}\")]\n    TemplateRenderingFailed { template_id: String, reason: String },\n    \n    #[error(\"Context optimization failed: {reason}\")]\n    ContextOptimizationFailed { reason: String },\n    \n    #[error(\"Knowledge access timeout: {timeout_ms}ms\")]\n    KnowledgeAccessTimeout { timeout_ms: u64 },\n    \n    #[error(\"Invalid context requirements: {details}\")]\n    InvalidContextRequirements { details: String },\n}\n\n/// Requirements for building AI context\n#[derive(Debug, Clone, Serialize, Deserialize)]\npub struct ContextRequirements {\n    /// Maximum token budget for the context\n    pub max_tokens: usize,\n    /// Required pattern types to include\n    pub required_patterns: Vec<String>,\n    /// Optional pattern types to include if space allows\n    pub optional_patterns: Vec<String>,\n    /// Target programming language\n    pub target_language: Option<SourceLanguage>,\n    /// Include code examples\n    pub include_examples: bool,\n    /// Include solution patterns\n    pub include_solutions: bool,\n    /// Include related patterns\n    pub include_related: bool,\n    /// Minimum confidence threshold\n    pub min_confidence: f64,\n    /// Context optimization level\n    pub optimization_level: OptimizationLevel,\n}\n\n#[derive(Debug, Clone, Serialize, Deserialize)]\npub enum OptimizationLevel {\n    None,\n    Basic,\n    Advanced,\n    Aggressive,\n}\n\n/// Enhanced prompt with knowledge context\n#[derive(Debug, Clone, Serialize)]\npub struct EnhancedPrompt {\n    pub base_prompt: String,\n    pub knowledge_context: String,\n    pub pattern_examples: Vec<CodeExample>,\n    pub solution_suggestions: Vec<SolutionPattern>,\n    pub token_count: usize,\n    pub confidence_score: f64,\n    pub metadata: PromptMetadata,\n}\n\n#[derive(Debug, Clone, Serialize)]\npub struct PromptMetadata {\n    pub patterns_included: Vec<String>,\n    pub generation_time_ms: u64,\n    pub optimization_applied: bool,\n    pub token_efficiency: f64, // tokens of knowledge / total tokens\n    pub coverage_score: f64,   // how well the context covers the issue\n}\n\n/// Context for detected patterns\n#[derive(Debug, Clone, Serialize)]\npub struct PatternContext {\n    pub primary_patterns: Vec<PatternKnowledge>,\n    pub related_patterns: Vec<PatternKnowledge>,\n    pub common_solutions: Vec<SolutionPattern>,\n    pub language_specific_guidance: Option<LanguageSpecificGuidance>,\n    pub severity_assessment: SeverityAssessment,\n    pub remediation_priority: RemediationPriority,\n}\n\n#[derive(Debug, Clone, Serialize)]\npub struct LanguageSpecificGuidance {\n    pub language: SourceLanguage,\n    pub specific_patterns: Vec<PatternKnowledge>,\n    pub tooling_recommendations: Vec<String>,\n    pub best_practices: Vec<String>,\n}\n\n#[derive(Debug, Clone, Serialize)]\npub struct SeverityAssessment {\n    pub overall_severity: ImpactLevel,\n    pub contributing_factors: Vec<String>,\n    pub risk_factors: Vec<String>,\n    pub urgency_score: f64,\n}\n\n#[derive(Debug, Clone, Serialize)]\npub enum RemediationPriority {\n    Critical,\n    High,\n    Medium,\n    Low,\n    Monitoring,\n}\n\n/// Related pattern suggestion\n#[derive(Debug, Clone, Serialize)]\npub struct RelatedPattern {\n    pub pattern: PatternKnowledge,\n    pub relationship_type: RelationshipType,\n    pub relevance_score: f64,\n    pub suggestion_reason: String,\n}\n\n#[derive(Debug, Clone, Serialize)]\npub enum RelationshipType {\n    CausedBy,\n    LeadsTo,\n    CoOccursWith,\n    SimilarTo,\n    AlternativeTo,\n    PrerequisiteFor,\n}\n\n/// Codebase context for pattern analysis\n#[derive(Debug, Clone)]\npub struct CodebaseContext {\n    pub languages: Vec<SourceLanguage>,\n    pub project_size: ProjectSize,\n    pub architectural_style: Option<ArchitecturalStyle>,\n    pub existing_patterns: HashSet<String>,\n    pub team_experience: ExperienceLevel,\n    pub constraints: Vec<ProjectConstraint>,\n}\n\n#[derive(Debug, Clone)]\npub enum ProjectSize {\n    Small,    // < 10k LOC\n    Medium,   // 10k - 100k LOC\n    Large,    // 100k - 1M LOC\n    Enterprise, // > 1M LOC\n}\n\n#[derive(Debug, Clone)]\npub enum ArchitecturalStyle {\n    Monolith,\n    Microservices,\n    Layered,\n    EventDriven,\n    Hexagonal,\n    Clean,\n}\n\n#[derive(Debug, Clone)]\npub enum ExperienceLevel {\n    Junior,\n    Intermediate,\n    Senior,\n    Expert,\n}\n\n#[derive(Debug, Clone)]\npub enum ProjectConstraint {\n    PerformanceCritical,\n    LegacyCodebase,\n    StrictCompliance,\n    ResourceConstrained,\n    RapidDevelopment,\n}\n\n/// Template engine for rendering prompts\npub struct TemplateEngine {\n    templates: HashMap<String, PromptTemplate>,\n    cache: Mutex<LruCache<String, String>>,\n}\n\n#[derive(Debug, Clone)]\npub struct PromptTemplate {\n    pub id: String,\n    pub name: String,\n    pub template: String,\n    pub required_variables: Vec<String>,\n    pub optional_variables: Vec<String>,\n    pub token_estimate: usize,\n}\n\nimpl TemplateEngine {\n    pub fn new() -> Self {\n        let mut templates = HashMap::new();\n        \n        // Add default templates\n        templates.insert(\n            \"pattern_analysis\".to_string(),\n            PromptTemplate {\n                id: \"pattern_analysis\".to_string(),\n                name: \"Pattern Analysis\".to_string(),\n                template: include_str!(\"templates/pattern_analysis.txt\").to_string(),\n                required_variables: vec![\"issue_description\".to_string(), \"patterns\".to_string()],\n                optional_variables: vec![\"examples\".to_string(), \"solutions\".to_string()],\n                token_estimate: 500,\n            },\n        );\n        \n        Self {\n            templates,\n            cache: Mutex::new(LruCache::new(100.try_into().unwrap())),\n        }\n    }\n    \n    pub fn render(&self, template_id: &str, variables: &HashMap<String, String>) -> Result<String, IntegrationError> {\n        let template = self.templates.get(template_id)\n            .ok_or_else(|| IntegrationError::TemplateRenderingFailed {\n                template_id: template_id.to_string(),\n                reason: \"Template not found\".to_string(),\n            })?;\n        \n        // Check required variables\n        for required_var in &template.required_variables {\n            if !variables.contains_key(required_var) {\n                return Err(IntegrationError::TemplateRenderingFailed {\n                    template_id: template_id.to_string(),\n                    reason: format!(\"Missing required variable: {}\", required_var),\n                });\n            }\n        }\n        \n        // Simple template rendering (in practice, you'd use a proper template engine)\n        let mut result = template.template.clone();\n        for (key, value) in variables {\n            result = result.replace(&format!(\"{{{{{}}}}}\", key), value);\n        }\n        \n        Ok(result)\n    }\n    \n    pub fn estimate_tokens(&self, template_id: &str, variables: &HashMap<String, String>) -> usize {\n        if let Some(template) = self.templates.get(template_id) {\n            let base_tokens = template.token_estimate;\n            let variable_tokens: usize = variables.values()\n                .map(|v| v.len() / 4) // Rough estimate: 4 chars per token\n                .sum();\n            base_tokens + variable_tokens\n        } else {\n            0\n        }\n    }\n}\n\n/// Context optimizer for efficient token usage\npub struct ContextOptimizer {\n    optimization_strategies: Vec<OptimizationStrategy>,\n}\n\n#[derive(Debug, Clone)]\npub enum OptimizationStrategy {\n    RemoveRedundantExamples,\n    SummarizeDescriptions,\n    PrioritizeByRelevance,\n    CompressWhitespace,\n    UseAbbreviations,\n}\n\nimpl ContextOptimizer {\n    pub fn new() -> Self {\n        Self {\n            optimization_strategies: vec![\n                OptimizationStrategy::RemoveRedundantExamples,\n                OptimizationStrategy::SummarizeDescriptions,\n                OptimizationStrategy::PrioritizeByRelevance,\n                OptimizationStrategy::CompressWhitespace,\n            ],\n        }\n    }\n    \n    pub fn optimize_context(\n        &self,\n        context: &str,\n        target_tokens: usize,\n        optimization_level: OptimizationLevel,\n    ) -> Result<String, IntegrationError> {\n        let mut optimized = context.to_string();\n        let mut current_tokens = self.estimate_tokens(&optimized);\n        \n        if current_tokens <= target_tokens {\n            return Ok(optimized);\n        }\n        \n        let strategies_to_use = match optimization_level {\n            OptimizationLevel::None => return Ok(optimized),\n            OptimizationLevel::Basic => &self.optimization_strategies[0..2],\n            OptimizationLevel::Advanced => &self.optimization_strategies[0..4],\n            OptimizationLevel::Aggressive => &self.optimization_strategies,\n        };\n        \n        for strategy in strategies_to_use {\n            optimized = self.apply_optimization_strategy(&optimized, strategy)?;\n            current_tokens = self.estimate_tokens(&optimized);\n            \n            if current_tokens <= target_tokens {\n                break;\n            }\n        }\n        \n        if current_tokens > target_tokens {\n            // Truncate if still over budget\n            let target_chars = (optimized.len() * target_tokens) / current_tokens;\n            optimized.truncate(target_chars);\n            optimized.push_str(\"...[truncated]\");\n        }\n        \n        Ok(optimized)\n    }\n    \n    fn apply_optimization_strategy(\n        &self,\n        content: &str,\n        strategy: &OptimizationStrategy,\n    ) -> Result<String, IntegrationError> {\n        match strategy {\n            OptimizationStrategy::CompressWhitespace => {\n                Ok(content.split_whitespace().collect::<Vec<_>>().join(\" \"))\n            }\n            OptimizationStrategy::SummarizeDescriptions => {\n                // Simple summarization - in practice, this would be more sophisticated\n                let lines: Vec<&str> = content.lines().collect();\n                let summarized: Vec<String> = lines\n                    .into_iter()\n                    .map(|line| {\n                        if line.len() > 100 {\n                            format!(\"{}...\", &line[..97])\n                        } else {\n                            line.to_string()\n                        }\n                    })\n                    .collect();\n                Ok(summarized.join(\"\\n\"))\n            }\n            _ => Ok(content.to_string()), // Placeholder for other strategies\n        }\n    }\n    \n    fn estimate_tokens(&self, content: &str) -> usize {\n        // Simple token estimation: roughly 4 characters per token\n        content.len() / 4\n    }\n}\n\n/// Token budget manager\npub struct TokenBudgetManager {\n    total_budget: usize,\n    reserved_for_prompt: usize,\n    reserved_for_response: usize,\n    available_for_context: usize,\n}\n\nimpl TokenBudgetManager {\n    pub fn new(total_budget: usize, prompt_ratio: f64, response_ratio: f64) -> Self {\n        let reserved_for_prompt = (total_budget as f64 * prompt_ratio) as usize;\n        let reserved_for_response = (total_budget as f64 * response_ratio) as usize;\n        let available_for_context = total_budget - reserved_for_prompt - reserved_for_response;\n        \n        Self {\n            total_budget,\n            reserved_for_prompt,\n            reserved_for_response,\n            available_for_context,\n        }\n    }\n    \n    pub fn allocate_context_budget(&self, context_size: usize) -> Result<usize, IntegrationError> {\n        if context_size > self.available_for_context {\n            return Err(IntegrationError::TokenBudgetExceeded {\n                current: context_size,\n                limit: self.available_for_context,\n            });\n        }\n        \n        Ok(self.available_for_context - context_size)\n    }\n    \n    pub fn get_available_context_tokens(&self) -> usize {\n        self.available_for_context\n    }\n}\n\n/// Smart prompt builder with knowledge integration\npub struct SmartPromptBuilder {\n    template_engine: TemplateEngine,\n    context_optimizer: ContextOptimizer,\n    token_budget_manager: TokenBudgetManager,\n}\n\nimpl SmartPromptBuilder {\n    pub fn new(token_budget: usize) -> Self {\n        Self {\n            template_engine: TemplateEngine::new(),\n            context_optimizer: ContextOptimizer::new(),\n            token_budget_manager: TokenBudgetManager::new(token_budget, 0.3, 0.3), // 40% for context\n        }\n    }\n    \n    pub fn build_enhanced_prompt(\n        &self,\n        template_id: &str,\n        base_variables: HashMap<String, String>,\n        pattern_context: &PatternContext,\n        requirements: &ContextRequirements,\n    ) -> Result<EnhancedPrompt, IntegrationError> {\n        let start_time = Instant::now();\n        \n        // Build knowledge context\n        let knowledge_context = self.build_knowledge_context(pattern_context, requirements)?;\n        \n        // Optimize context to fit token budget\n        let available_tokens = self.token_budget_manager.get_available_context_tokens();\n        let optimized_context = self.context_optimizer.optimize_context(\n            &knowledge_context,\n            available_tokens,\n            requirements.optimization_level.clone(),\n        )?;\n        \n        // Prepare template variables\n        let mut variables = base_variables;\n        variables.insert(\"knowledge_context\".to_string(), optimized_context.clone());\n        \n        // Render the prompt\n        let base_prompt = self.template_engine.render(template_id, &variables)?;\n        \n        // Calculate metrics\n        let token_count = self.estimate_total_tokens(&base_prompt, &optimized_context);\n        let confidence_score = self.calculate_confidence_score(pattern_context, requirements);\n        \n        let patterns_included: Vec<String> = pattern_context.primary_patterns\n            .iter()\n            .chain(pattern_context.related_patterns.iter())\n            .map(|p| p.id.clone())\n            .collect();\n        \n        let token_efficiency = optimized_context.len() as f64 / token_count as f64;\n        let coverage_score = self.calculate_coverage_score(pattern_context, requirements);\n        \n        Ok(EnhancedPrompt {\n            base_prompt,\n            knowledge_context: optimized_context,\n            pattern_examples: self.extract_examples(pattern_context, requirements),\n            solution_suggestions: pattern_context.common_solutions.clone(),\n            token_count,\n            confidence_score,\n            metadata: PromptMetadata {\n                patterns_included,\n                generation_time_ms: start_time.elapsed().as_millis() as u64,\n                optimization_applied: requirements.optimization_level != OptimizationLevel::None,\n                token_efficiency,\n                coverage_score,\n            },\n        })\n    }\n    \n    fn build_knowledge_context(\n        &self,\n        pattern_context: &PatternContext,\n        requirements: &ContextRequirements,\n    ) -> Result<String, IntegrationError> {\n        let mut context_parts = Vec::new();\n        \n        // Add primary patterns\n        if !pattern_context.primary_patterns.is_empty() {\n            context_parts.push(\"## Primary Anti-Patterns Detected\".to_string());\n            for pattern in &pattern_context.primary_patterns {\n                context_parts.push(self.format_pattern_for_context(pattern, requirements));\n            }\n        }\n        \n        // Add related patterns if requested\n        if requirements.include_related && !pattern_context.related_patterns.is_empty() {\n            context_parts.push(\"## Related Patterns\".to_string());\n            for pattern in &pattern_context.related_patterns {\n                context_parts.push(self.format_pattern_for_context(pattern, requirements));\n            }\n        }\n        \n        // Add solutions if requested\n        if requirements.include_solutions && !pattern_context.common_solutions.is_empty() {\n            context_parts.push(\"## Recommended Solutions\".to_string());\n            for solution in &pattern_context.common_solutions {\n                context_parts.push(format!(\n                    \"**{}**: {}\",\n                    solution.title,\n                    solution.implementation.get_content()\n                ));\n            }\n        }\n        \n        // Add severity assessment\n        context_parts.push(\"## Severity Assessment\".to_string());\n        context_parts.push(format!(\n            \"Overall Severity: {:?}\\nUrgency Score: {:.2}\",\n            pattern_context.severity_assessment.overall_severity,\n            pattern_context.severity_assessment.urgency_score\n        ));\n        \n        Ok(context_parts.join(\"\\n\\n\"))\n    }\n    \n    fn format_pattern_for_context(\n        &self,\n        pattern: &PatternKnowledge,\n        requirements: &ContextRequirements,\n    ) -> String {\n        let mut parts = vec![\n            format!(\"### {}\", pattern.name),\n            format!(\"**Definition**: {}\", pattern.definition.get_content()),\n        ];\n        \n        if !pattern.symptoms.is_empty() {\n            let symptoms: Vec<String> = pattern.symptoms\n                .iter()\n                .take(3) // Limit to first 3 symptoms to save tokens\n                .map(|s| s.get_content())\n                .collect();\n            parts.push(format!(\"**Symptoms**: {}\", symptoms.join(\", \")));\n        }\n        \n        if requirements.include_examples {\n            // Add examples if available and requested\n            if !pattern.examples.primary.is_empty() {\n                parts.push(\"**Example**:\".to_string());\n                if let Some(example) = pattern.examples.primary.first() {\n                    parts.push(format!(\"```{}\\n{}\\n```\", \n                        example.language.to_string().to_lowercase(), \n                        example.code\n                    ));\n                }\n            }\n        }\n        \n        parts.join(\"\\n\")\n    }\n    \n    fn extract_examples(\n        &self,\n        pattern_context: &PatternContext,\n        requirements: &ContextRequirements,\n    ) -> Vec<CodeExample> {\n        if !requirements.include_examples {\n            return Vec::new();\n        }\n        \n        let mut examples = Vec::new();\n        \n        for pattern in &pattern_context.primary_patterns {\n            examples.extend(pattern.examples.primary.iter().cloned());\n        }\n        \n        // Limit examples to save tokens\n        examples.truncate(3);\n        examples\n    }\n    \n    fn estimate_total_tokens(&self, base_prompt: &str, context: &str) -> usize {\n        (base_prompt.len() + context.len()) / 4 // Simple estimation\n    }\n    \n    fn calculate_confidence_score(\n        &self,\n        pattern_context: &PatternContext,\n        _requirements: &ContextRequirements,\n    ) -> f64 {\n        if pattern_context.primary_patterns.is_empty() {\n            return 0.0;\n        }\n        \n        let avg_confidence: f64 = pattern_context.primary_patterns\n            .iter()\n            .map(|p| p.detection_confidence)\n            .sum::<f64>() / pattern_context.primary_patterns.len() as f64;\n        \n        // Boost confidence if we have multiple corroborating patterns\n        let pattern_count_bonus = (pattern_context.primary_patterns.len() as f64 * 0.1).min(0.2);\n        \n        (avg_confidence + pattern_count_bonus).min(1.0)\n    }\n    \n    fn calculate_coverage_score(\n        &self,\n        pattern_context: &PatternContext,\n        requirements: &ContextRequirements,\n    ) -> f64 {\n        let mut covered_requirements = 0;\n        let total_requirements = requirements.required_patterns.len() + requirements.optional_patterns.len();\n        \n        if total_requirements == 0 {\n            return 1.0;\n        }\n        \n        let pattern_ids: HashSet<String> = pattern_context.primary_patterns\n            .iter()\n            .chain(pattern_context.related_patterns.iter())\n            .map(|p| p.id.clone())\n            .collect();\n        \n        for required in &requirements.required_patterns {\n            if pattern_ids.contains(required) {\n                covered_requirements += 1;\n            }\n        }\n        \n        for optional in &requirements.optional_patterns {\n            if pattern_ids.contains(optional) {\n                covered_requirements += 1;\n            }\n        }\n        \n        covered_requirements as f64 / total_requirements as f64\n    }\n}\n\n/// Main AI knowledge integration system\npub struct AIKnowledgeIntegration {\n    knowledge_access: Arc<ConcurrentKnowledgeAccess>,\n    prompt_builder: SmartPromptBuilder,\n    context_cache: RwLock<LruCache<String, PatternContext>>,\n    default_token_budget: usize,\n}\n\nimpl AIKnowledgeIntegration {\n    pub fn new(\n        knowledge_access: Arc<ConcurrentKnowledgeAccess>,\n        default_token_budget: usize,\n    ) -> Self {\n        Self {\n            knowledge_access,\n            prompt_builder: SmartPromptBuilder::new(default_token_budget),\n            context_cache: RwLock::new(LruCache::new(100.try_into().unwrap())),\n            default_token_budget,\n        }\n    }\n    \n    /// Build enhanced prompt with knowledge context\n    pub async fn build_enhanced_prompt(\n        &self,\n        issue: &ArchitecturalIssue,\n        context_requirements: &ContextRequirements,\n    ) -> Result<EnhancedPrompt, IntegrationError> {\n        // Extract pattern information from the issue\n        let pattern_types = self.extract_pattern_types_from_issue(issue);\n        \n        // Get pattern context\n        let pattern_context = self.get_pattern_context(\n            &pattern_types,\n            context_requirements.target_language.unwrap_or(SourceLanguage::Universal),\n        ).await?;\n        \n        // Build base variables for the prompt\n        let mut base_variables = HashMap::new();\n        base_variables.insert(\"issue_description\".to_string(), issue.description.clone());\n        base_variables.insert(\"issue_severity\".to_string(), format!(\"{:?}\", issue.severity));\n        \n        // Build the enhanced prompt\n        self.prompt_builder.build_enhanced_prompt(\n            \"pattern_analysis\",\n            base_variables,\n            &pattern_context,\n            context_requirements,\n        )\n    }\n    \n    /// Get contextual knowledge for detected patterns\n    pub async fn get_pattern_context(\n        &self,\n        pattern_types: &[String],\n        language: SourceLanguage,\n    ) -> Result<PatternContext, IntegrationError> {\n        let cache_key = format!(\"{:?}_{:?}\", pattern_types, language);\n        \n        // Check cache first\n        {\n            let cache = self.context_cache.read().await;\n            if let Some(cached) = cache.get(&cache_key) {\n                return Ok(cached.clone());\n            }\n        }\n        \n        // Fetch patterns from knowledge library\n        let mut primary_patterns = Vec::new();\n        let mut related_patterns = Vec::new();\n        \n        for pattern_id in pattern_types {\n            if let Ok(pattern) = self.knowledge_access.get_pattern_concurrent(pattern_id).await {\n                let pattern_data = (*pattern).clone();\n                primary_patterns.push(pattern_data.clone());\n                \n                // Get related patterns\n                for related_id in &pattern_data.related_patterns {\n                    if let Ok(related) = self.knowledge_access.get_pattern_concurrent(related_id).await {\n                        related_patterns.push((*related).clone());\n                    }\n                }\n            }\n        }\n        \n        if primary_patterns.is_empty() {\n            return Err(IntegrationError::PatternContextNotFound {\n                pattern_id: pattern_types.join(\", \"),\n            });\n        }\n        \n        // Extract common solutions\n        let common_solutions = self.extract_common_solutions(&primary_patterns);\n        \n        // Build severity assessment\n        let severity_assessment = self.assess_severity(&primary_patterns);\n        \n        // Determine remediation priority\n        let remediation_priority = self.determine_remediation_priority(&severity_assessment);\n        \n        // Build language-specific guidance\n        let language_specific_guidance = if language != SourceLanguage::Universal {\n            Some(self.build_language_guidance(&primary_patterns, language).await?)\n        } else {\n            None\n        };\n        \n        let context = PatternContext {\n            primary_patterns,\n            related_patterns,\n            common_solutions,\n            language_specific_guidance,\n            severity_assessment,\n            remediation_priority,\n        };\n        \n        // Cache the result\n        {\n            let mut cache = self.context_cache.write().await;\n            cache.put(cache_key, context.clone());\n        }\n        \n        Ok(context)\n    }\n    \n    /// Suggest related patterns for comprehensive analysis\n    pub async fn suggest_related_patterns(\n        &self,\n        base_pattern: &str,\n        codebase_context: &CodebaseContext,\n    ) -> Result<Vec<RelatedPattern>, IntegrationError> {\n        let base_pattern_data = self.knowledge_access\n            .get_pattern_concurrent(base_pattern)\n            .await\n            .map_err(|_| IntegrationError::PatternContextNotFound {\n                pattern_id: base_pattern.to_string(),\n            })?;\n        \n        let mut suggestions = Vec::new();\n        \n        // Get explicitly related patterns\n        for related_id in &base_pattern_data.related_patterns {\n            if let Ok(related) = self.knowledge_access.get_pattern_concurrent(related_id).await {\n                suggestions.push(RelatedPattern {\n                    pattern: (*related).clone(),\n                    relationship_type: RelationshipType::SimilarTo,\n                    relevance_score: 0.8,\n                    suggestion_reason: \"Explicitly related pattern\".to_string(),\n                });\n            }\n        }\n        \n        // Get patterns that commonly co-occur\n        let co_occurring = self.find_co_occurring_patterns(&base_pattern_data, codebase_context).await?;\n        for pattern in co_occurring {\n            suggestions.push(RelatedPattern {\n                pattern,\n                relationship_type: RelationshipType::CoOccursWith,\n                relevance_score: 0.6,\n                suggestion_reason: \"Commonly occurs together\".to_string(),\n            });\n        }\n        \n        // Sort by relevance score\n        suggestions.sort_by(|a, b| b.relevance_score.partial_cmp(&a.relevance_score).unwrap());\n        \n        // Limit to top 5 suggestions\n        suggestions.truncate(5);\n        \n        Ok(suggestions)\n    }\n    \n    fn extract_pattern_types_from_issue(&self, issue: &ArchitecturalIssue) -> Vec<String> {\n        // Extract pattern types from the issue\n        // This would analyze the issue description, detected patterns, etc.\n        // For now, we'll use a simple approach\n        \n        let mut pattern_types = Vec::new();\n        \n        // Check issue description for pattern keywords\n        let description_lower = issue.description.to_lowercase();\n        \n        if description_lower.contains(\"god object\") || description_lower.contains(\"large class\") {\n            pattern_types.push(\"god_object\".to_string());\n        }\n        \n        if description_lower.contains(\"magic number\") || description_lower.contains(\"hard coded\") {\n            pattern_types.push(\"magic_numbers\".to_string());\n        }\n        \n        if description_lower.contains(\"cyclic\") || description_lower.contains(\"circular\") {\n            pattern_types.push(\"cyclic_dependencies\".to_string());\n        }\n        \n        // If no specific patterns detected, use a default\n        if pattern_types.is_empty() {\n            pattern_types.push(\"general_code_smell\".to_string());\n        }\n        \n        pattern_types\n    }\n    \n    fn extract_common_solutions(&self, patterns: &[PatternKnowledge]) -> Vec<SolutionPattern> {\n        let mut solution_map: HashMap<String, SolutionPattern> = HashMap::new();\n        \n        for pattern in patterns {\n            for solution in &pattern.solutions {\n                solution_map.insert(solution.id.clone(), solution.clone());\n            }\n        }\n        \n        solution_map.into_values().collect()\n    }\n    \n    fn assess_severity(&self, patterns: &[PatternKnowledge]) -> SeverityAssessment {\n        let overall_severity = patterns\n            .iter()\n            .map(|p| &p.impact)\n            .max()\n            .cloned()\n            .unwrap_or(ImpactLevel::Low);\n        \n        let contributing_factors: Vec<String> = patterns\n            .iter()\n            .map(|p| p.name.clone())\n            .collect();\n        \n        let risk_factors = vec![\n            \"Code maintainability\".to_string(),\n            \"Development velocity\".to_string(),\n            \"Technical debt accumulation\".to_string(),\n        ];\n        \n        let urgency_score = match overall_severity {\n            ImpactLevel::Critical => 1.0,\n            ImpactLevel::High => 0.8,\n            ImpactLevel::Medium => 0.6,\n            ImpactLevel::Low => 0.3,\n        };\n        \n        SeverityAssessment {\n            overall_severity,\n            contributing_factors,\n            risk_factors,\n            urgency_score,\n        }\n    }\n    \n    fn determine_remediation_priority(&self, assessment: &SeverityAssessment) -> RemediationPriority {\n        match assessment.overall_severity {\n            ImpactLevel::Critical => RemediationPriority::Critical,\n            ImpactLevel::High => RemediationPriority::High,\n            ImpactLevel::Medium => RemediationPriority::Medium,\n            ImpactLevel::Low => RemediationPriority::Low,\n        }\n    }\n    \n    async fn build_language_guidance(\n        &self,\n        patterns: &[PatternKnowledge],\n        language: SourceLanguage,\n    ) -> Result<LanguageSpecificGuidance, IntegrationError> {\n        // Get language-specific patterns\n        let language_patterns = self.knowledge_access\n            .get_pattern_concurrent(&format!(\"{:?}_patterns\", language))\n            .await\n            .map(|p| vec![(*p).clone()])\n            .unwrap_or_default();\n        \n        let tooling_recommendations = match language {\n            SourceLanguage::Rust => vec![\n                \"cargo clippy\".to_string(),\n                \"cargo audit\".to_string(),\n                \"rustfmt\".to_string(),\n            ],\n            SourceLanguage::Python => vec![\n                \"pylint\".to_string(),\n                \"flake8\".to_string(),\n                \"black\".to_string(),\n                \"mypy\".to_string(),\n            ],\n            SourceLanguage::JavaScript => vec![\n                \"eslint\".to_string(),\n                \"prettier\".to_string(),\n                \"typescript\".to_string(),\n            ],\n            _ => vec![],\n        };\n        \n        let best_practices = match language {\n            SourceLanguage::Rust => vec![\n                \"Use ownership and borrowing effectively\".to_string(),\n                \"Prefer iterators over manual loops\".to_string(),\n                \"Use Result and Option types for error handling\".to_string(),\n            ],\n            SourceLanguage::Python => vec![\n                \"Follow PEP 8 style guidelines\".to_string(),\n                \"Use type hints for better code clarity\".to_string(),\n                \"Prefer list comprehensions over loops when appropriate\".to_string(),\n            ],\n            SourceLanguage::JavaScript => vec![\n                \"Use const and let instead of var\".to_string(),\n                \"Prefer async/await over callback patterns\".to_string(),\n                \"Use destructuring for cleaner code\".to_string(),\n            ],\n            _ => vec![],\n        };\n        \n        Ok(LanguageSpecificGuidance {\n            language,\n            specific_patterns: language_patterns,\n            tooling_recommendations,\n            best_practices,\n        })\n    }\n    \n    async fn find_co_occurring_patterns(\n        &self,\n        _base_pattern: &PatternKnowledge,\n        _codebase_context: &CodebaseContext,\n    ) -> Result<Vec<PatternKnowledge>, IntegrationError> {\n        // In a real implementation, this would analyze historical data\n        // to find patterns that commonly occur together\n        // For now, return empty vec\n        Ok(Vec::new())\n    }\n}\n\n#[cfg(test)]\nmod tests {\n    use super::*;\n    \n    #[test]\n    fn test_context_requirements_creation() {\n        let requirements = ContextRequirements {\n            max_tokens: 1000,\n            required_patterns: vec![\"god_object\".to_string()],\n            optional_patterns: vec![\"magic_numbers\".to_string()],\n            target_language: Some(SourceLanguage::Rust),\n            include_examples: true,\n            include_solutions: true,\n            include_related: false,\n            min_confidence: 0.8,\n            optimization_level: OptimizationLevel::Advanced,\n        };\n        \n        assert_eq!(requirements.max_tokens, 1000);\n        assert_eq!(requirements.required_patterns.len(), 1);\n        assert!(requirements.include_examples);\n    }\n    \n    #[test]\n    fn test_token_budget_manager() {\n        let manager = TokenBudgetManager::new(1000, 0.3, 0.3);\n        assert_eq!(manager.get_available_context_tokens(), 400);\n        \n        let result = manager.allocate_context_budget(300);\n        assert!(result.is_ok());\n        assert_eq!(result.unwrap(), 100);\n        \n        let over_budget = manager.allocate_context_budget(500);\n        assert!(over_budget.is_err());\n    }\n    \n    #[test]\n    fn test_template_engine() {\n        let engine = TemplateEngine::new();\n        \n        let mut variables = HashMap::new();\n        variables.insert(\"issue_description\".to_string(), \"Test issue\".to_string());\n        variables.insert(\"patterns\".to_string(), \"Test patterns\".to_string());\n        \n        // This would fail because we don't have the actual template file\n        // but it tests the error handling\n        let result = engine.render(\"nonexistent_template\", &variables);\n        assert!(result.is_err());\n    }\n    \n    #[test]\n    fn test_context_optimizer() {\n        let optimizer = ContextOptimizer::new();\n        \n        let content = \"This is a test content that is quite long and should be optimized for token usage.\";\n        let result = optimizer.optimize_context(\n            content,\n            10, // Very low token budget to force optimization\n            OptimizationLevel::Advanced,\n        );\n        \n        assert!(result.is_ok());\n        let optimized = result.unwrap();\n        assert!(optimized.len() <= content.len());\n    }\n}"